 const seriesNote=make('p'),status=make('p');status.setAttribute('role','status');const resultHost=make('div'),detail=make('details'),canvas=make('canvas');canvas.setAttribute('role','img');canvas.setAttribute('aria-label','Пользовательский график анализа');
 function field(key,title,choices){const label=make('label',title),input=make(choices?'select':'input');input.name=key;controls[key]=input;if(choices)for(const [value,text]of choices){const o=make('option',text);o.value=value;input.append(o);}else{input.type=['start','end','width','maxChild'].includes(key)?'number':'text';if(input.type==='number'){input.min=key==='start'?0:key==='maxChild'?1:.1;input.step=key==='maxChild'?1:'any';}input.maxLength=600;}label.append(input);grid.append(label);return input;}
 field('name','Название показателя');field('expression','Значение или формула');field('filter','Условие отбора особей');
 field('aggregate','Расчёт',[['mean','Среднее'],['median','Медиана'],['percent','Доля выполнения условия, %'],['count','Количество отобранных особей на мир (среднее)'],['sum','Сумма значений на мир (среднее)']]);
 field('axis','Ось X',[['born','Период рождения родителей'],['child','Номер ребёнка']]);field('group','Группировать по',[['','Все выбранные варианты']]);field('split','Дополнительно разделить по',[['','Не разделять']]);
 field('start','Рождения родителей от, Т');field('end','Рождения родителей до, Т');field('width','Ширина временного интервала, Т');field('maxChild','Номера детей от 1 до (не более 20)');
